def extents(path):
    fd=os.open(path,os.O_RDONLY);out=[]
    try:
        size=os.fstat(fd).st_size;offset=0
        while offset<size:
            try:start=os.lseek(fd,offset,os.SEEK_DATA)
            except OSError as e:
                if e.errno==errno.ENXIO:break
                raise
            end=min(os.lseek(fd,start,os.SEEK_HOLE),size)
            if end<=start:raise OSError('non-progress extent')
            out.append((start,end));offset=end
        return out
    finally:os.close(fd)
